INSERT INTO `Article` (`id`, `titre`, `resume`, `contenu`, `date_creation`, `date_publication`, `auteur_id`, `categorie_id`) VALUES
(1,	'Mario fête ses 40 ans cette année',	'Depuis 40 ans, Mario accompagne des générations de joueurs à travers des aventures iconiques. Cet article revient sur l’évolution du plombier le plus célèbre du jeu vidéo et son impact culturel immense.',	'### 40 ans déjà : Mario, une icône intergénérationnelle\r\nEn 1985, *Super Mario Bros.* débarquait sur NES et changeait à jamais l’histoire du jeu vidéo.  \r\nQuarante ans plus tard, Mario reste l’un des personnages les plus reconnaissables au monde, symbole de Nintendo et véritable pilier de la culture pop.\r\n\r\n### Une évolution constante\r\nMario n’a jamais cessé d’évoluer.  \r\nDes jeux en 2D aux mondes ouverts modernes, chaque génération a eu son Mario :\r\n\r\n- **1985** – *Super Mario Bros.* révolutionne le platformer.  \r\n- **1992** – *Super Mario Kart* introduit pour la première fois les personnages de l’univers Mario dans un jeu de course. Avec son style unique, ses circuits variés et son gameplay accessible mais technique.  \r\n- **1995** – *Super Mario World 2: Yoshi\'s Island* propose une direction artistique dessinée à la main, colorée et intemporelle. Le style crayonné et l’animation fluide donnent au jeu un charme unique, et Yoshi y brille dans un gameplay qui n’a presque pas vieilli malgré son âge.  \r\n- **1996** – *Super Mario 64* redéfinit la 3D.  \r\n- **2007** – *Super Mario Galaxy* introduit un gameplay révolutionnaire basé sur la gravité et des planètes miniatures, offrant une expérience unique encore inégalée aujourd’hui.  \r\n- **2017** – *Super Mario Odyssey* modernise la formule avec une liberté totale.  \r\n\r\nChaque épisode a repoussé les limites techniques et artistiques de son époque.\r\n\r\n### Un impact culturel mondial\r\nMario dépasse largement le cadre du jeu vidéo.  \r\nOn le retrouve dans :\r\n\r\n- des films (*Super Mario Le Film*, *Super Mario Galaxy Le Film*)  \r\n- des jouets (*My Mario*)  \r\n- des compétitions esport (*Tournois Mario Kart*)  \r\n- des parcs d’attractions (*Super Nintendo World*)  \r\n\r\nIl est devenu un symbole universel, reconnaissable même par ceux qui n’ont jamais touché une console.\r\n\r\n### Pourquoi Mario dure encore\r\nSa longévité s’explique par plusieurs facteurs :\r\n\r\n- **accessibilité** : simple à comprendre, difficile à maîtriser  \r\n- **innovation constante** : chaque jeu apporte une idée forte  \r\n- **identité visuelle forte** : couleurs, formes, musiques  \r\n- **nostalgie** : Mario fait partie de l’enfance de millions de joueurs  \r\n\r\nMario n’est pas juste un personnage, c’est un langage commun entre générations, mais surtout ``C’est pas un jeu Mario c’est une licence`` (Xabab).\r\n\r\n![Super Mario Galaxy Le Film](https://sm.ign.com/t/ign_fr/news/t/the-super-/the-super-mario-galaxy-movie-nintendo-direct-everything-anno_5k6j.1200.jpg)',	'2026-06-15 09:04:24',	'2026-06-16 08:19:00',	1,	1),
(4,	'Les loups, un prédateur essentiel aux écosystèmes',	'Les loups jouent un rôle majeur dans l’équilibre des milieux naturels. Leur présence influence la dynamique des populations d’herbivores et contribue à maintenir la diversité des habitats.',	'Le loup est un mammifère carnivore vivant en meute et occupant un rôle central dans la régulation des écosystèmes. Sa présence, longtemps menacée, revient progressivement dans plusieurs régions d’Europe.\r\n\r\n![Image d\'un loup](https://leo-t-88.github.io/assets/avatar.jpg)\r\n\r\n### Organisation sociale  \r\nLes loups vivent en groupes structurés autour d’un couple reproducteur. La meute coopère pour la chasse, la défense du territoire et l’éducation des jeunes. Cette organisation permet une grande efficacité dans la recherche de nourriture.\r\n\r\n### Rôle écologique  \r\nEn régulant les populations d’ongulés comme les cerfs ou les chevreuils, les loups limitent la surconsommation de la végétation. Cela favorise la régénération des forêts, la diversité des plantes et l’équilibre global de l’habitat.\r\n\r\n### Relations avec l’humain  \r\nLe retour du loup entraîne parfois des tensions, notamment dans les zones d’élevage. Des mesures de protection, comme les clôtures renforcées ou la présence de chiens de garde, permettent de réduire les conflits tout en préservant l’espèce.\r\n\r\n### Conclusion  \r\nLe loup reste un animal fascinant et indispensable au bon fonctionnement des milieux naturels. Sa conservation nécessite un équilibre entre protection de la biodiversité et activités humaines.',	'2026-06-15 13:25:10',	'2026-06-15 13:29:17',	1,	2),
(6,	'Nancy Open Air sublimé par l’univers musical de Clair Obscur : Expedition 33',	'Le concert Clair Obscur : Expedition 33 a transformé l’amphithéâtre du Zénith du Grand Nancy en un espace suspendu, où près de 10 000 spectateurs ont vécu une expérience musicale rare. Portée par l’orchestre Curieux, la soprano Alice Duport-Percier et le compositeur Lorien Testard, cette représentation en plein air a mêlé puissance orchestrale, influences électroniques et émotions visuelles, confirmant l’ampleur du phénomène autour du jeu vidéo français récompensé aux The Games Awards 2025.',	'### Un événement qui marque un tournant pour le Nancy Open Air\r\nLe Nancy Open Air a offert une soirée mémorable en accueillant pour la première fois en plein air la bande originale de Clair Obscur : Expedition 33. Après l’intensité du Heavy Week-End, l’amphithéâtre du Zénith a changé d’atmosphère pour accueillir un public venu de toute l’Europe. Près de 10 000 personnes se sont installées pour découvrir une œuvre musicale déjà culte, portée par un jeu vidéo devenu un phénomène mondial. L’ambiance, à la fois attentive et émerveillée, a montré à quel point cette création dépasse le simple cadre du divertissement.\r\n\r\n![Lorien Testard et Alice Duport-Percier, avec l’orchestre Curieux se sont produits devant 10 000 personnes.  Photo Alexandre Marchi](https://cdn-s-www.estrepublicain.fr/images/bcdcc1c2-573e-4994-81b6-12c6bdfca554/NW_raw/lorien-testard-et-alice-duport-percier-avec-l-orchestre-curieux-se-sont-produits-devant-10-000-personnes-photo-alexandre-marchi-1781303868.jpg)\r\n\r\n### Une performance artistique d’une grande exigence\r\nLe compositeur Lorien Testard, accompagné de la soprano Alice Duport-Percier et de l’orchestre Curieux dirigé par Daniel Sicard, a donné vie à une partition dense, riche et profondément narrative. Pendant plus de deux heures, les musiciens ont alterné entre passages orchestraux majestueux, textures électroniques et moments plus intimistes, évoquant les personnages emblématiques du jeu comme Lune, Sciel ou encore Verso. Cette fusion entre musique classique, guitare électrique et accordéon a offert une identité sonore unique, témoignant du savoir-faire français dans la création musicale contemporaine.\r\n\r\n### Un public conquis et une œuvre déjà légendaire\r\nL’engouement autour de l’événement s’est ressenti bien avant le début du concert, notamment à travers un merchandising pris d’assaut par des fans venus parfois de très loin. Une fois la représentation lancée, chaque tableau musical a suscité une attention quasi religieuse, jusqu’à une standing ovation finale sous une pluie de confettis évoquant des pétales de rose. Cette soirée a confirmé que Clair Obscur : Expedition 33 appartient désormais au cercle restreint des œuvres dont chaque représentation devient un moment de grâce, comparable aux grandes sagas cinématographiques ayant marqué l’histoire de la musique orchestrale.',	'2026-06-16 07:21:05',	'2026-06-16 07:21:07',	1,	1),
(8,	'Majorana 2, la nouvelle génération de qubits topologiques selon Microsoft',	'Majorana 2 représente une étape clé dans la stratégie quantique de Microsoft. Le projet vise à démontrer la viabilité des qubits topologiques, une approche conçue pour obtenir des systèmes quantiques plus stables et plus fiables que les technologies actuelles. En combinant avancées théoriques, ingénierie de pointe et collaborations scientifiques, Microsoft cherche à franchir un cap décisif vers un ordinateur quantique réellement scalable et exploitable.',	'### Un jalon essentiel dans la feuille de route quantique de Microsoft\r\nMajorana 2 s’inscrit dans la continuité des travaux menés par Microsoft pour développer des qubits topologiques, une technologie considérée comme l’une des plus prometteuses pour dépasser les limites des architectures quantiques actuelles. Contrairement aux qubits supraconducteurs ou ioniques, les qubits topologiques sont conçus pour être naturellement protégés contre certaines formes de bruit, ce qui pourrait réduire considérablement les erreurs. Avec Majorana 2, Microsoft cherche à démontrer expérimentalement que cette approche peut offrir une base plus stable et plus fiable pour un futur ordinateur quantique industriel.\r\n\r\n### Une exploration approfondie des fermions de Majorana\r\nLe projet tire son nom des fermions de Majorana, des quasi‑particules théoriques capables d’être leur propre antiparticule. Microsoft explore depuis plusieurs années leur potentiel pour créer des qubits plus robustes, capables de maintenir un état quantique plus longtemps. Majorana 2 marque une nouvelle phase d’expérimentation, avec des dispositifs plus avancés, des mesures plus précises et une meilleure compréhension des phénomènes physiques impliqués. Cette étape vise à confirmer que les signatures observées correspondent bien aux comportements attendus d’un système topologique exploitable.\r\n\r\n### Une ambition claire : construire un ordinateur quantique scalable\r\nL’objectif final de Majorana 2 dépasse la simple validation scientifique. Microsoft cherche à construire un ordinateur quantique capable de résoudre des problèmes impossibles à traiter avec les machines classiques. Pour y parvenir, il faut des qubits fiables, reproductibles et intégrables à grande échelle. Majorana 2 représente donc un jalon stratégique dans cette feuille de route, en cherchant à prouver que les qubits topologiques peuvent constituer une base solide pour un système quantique industriel. Si cette approche réussit, elle pourrait transformer durablement le paysage de l’informatique quantique et ouvrir la voie à de nouvelles applications.',	'2026-06-16 07:45:07',	'2026-06-16 07:45:09',	1,	3),
(9,	'Les musiques iconiques qui ont marqué l’histoire du jeu vidéo',	'Les musiques de jeux vidéo ont profondément influencé la manière dont les joueurs vivent leurs aventures. Des œuvres comme Zelda: Ocarina of Time, Final Fantasy VII, Skyrim, Hollow Knight ont démontré que la bande‑son peut devenir un élément central de l’expérience, capable de créer des émotions durables et d’élever un jeu au rang d’œuvre culturelle.',	'### Quand la musique devient l’âme d’un univers vidéoludique\r\nLes bandes-son de jeux vidéo ont évolué pour devenir des éléments essentiels de l’identité d’un titre. Des compositions comme celles de *Zelda: Ocarina of Time*, *Super Mario Galaxy* ou *The Witcher 3* montrent comment une mélodie peut définir un lieu, une ambiance ou un moment clé. Ces musiques, souvent reconnaissables dès les premières notes, accompagnent le joueur tout au long de son aventure et renforcent l’immersion.\r\n\r\n![Link playing ocarina, The Legend of Zelda : Ocarina of Time](https://static.wikia.nocookie.net/zelda/images/1/19/Sheik_OoT3D.png/revision/latest?cb=20130626200207&path-prefix=fr)\r\n\r\n### Des émotions amplifiées par des œuvres marquantes\r\nCertains jeux utilisent la musique pour transmettre des émotions profondes, comme *Hollow Knight* avec ses thèmes mélancoliques. *Final Fantasy VII* et *Undertale* démontrent également comment une bande-son peut devenir un vecteur narratif puissant, capable de renforcer l’impact d’une scène ou d’un combat. La musique devient alors un langage à part entière, guidant le joueur sans jamais interrompre le rythme du jeu.\r\n\r\n![Hornet playing music Hollow Knight : Silksong](https://i.ytimg.com/vi/vxqMzXxjcmM/maxresdefault.jpg)\r\n\r\n### Des bandes-son devenues des références culturelles\r\nAu fil des années, certaines musiques ont dépassé le cadre du jeu vidéo pour entrer dans la culture populaire. *Skyrim*, *Journey*, *Celeste* ou encore *Halo* sont régulièrement joués en concert symphonique, preuve de leur influence artistique. Ces œuvres montrent que la musique peut transformer une simple aventure en expérience mémorable, marquant durablement les joueurs. Elles illustrent aussi la maturité croissante du jeu vidéo en tant que média culturel.',	'2026-06-16 08:03:34',	'2026-06-16 08:03:35',	1,	1),
